diff --git a/src/commands/review.ts b/src/commands/review.ts
index 0123456..89abcde 100644
--- a/src/commands/review.ts
+++ b/src/commands/review.ts
@@ -10,8 +10,16 @@ export function registerReviewCommand() {
-  registerCommand("pr", runReview);
+  registerCommand("pr", runReview);
+  registerCommand("pr-dev", runFixtureRender);
+  // Development command intentionally bypasses the agent loop.
+  // It renders static JSON and static git metadata through the real renderer.
   return true;
 }
@@ -44,6 +52,12 @@ function runReview(args) {
+function runFixtureRender(args) {
+  return execCli(["dev-render", ...args]);
+}

