+++ b/src/templates/chapters.ts
@@ -80,7 +80,12 @@ function renderOverview(report) {
-  return `<section>${summary}</section>`;
+  return `<section id="overview" class="review-overview">${summary}</section>`;
+}
+
+function renderResponsiveStressRow(label: string, value: string): string {
+  return `<tr><th>${label}</th><td>${value}</td></tr>`;
 }
@@ -145,6 +150,8 @@ function renderChapterBody(chapters) {
+// Fixture includes this intentionally long line to exercise horizontal scrolling, wrapping, and diff overflow behavior in narrow browser widths: const reviewFixtureStressValue = "abcdefghijklmnopqrstuvwxyz-0123456789-ABCDEFGHIJKLMNOPQRSTUVWXYZ-this-segment-keeps-going-to-force-overflow-and-verify-that-the-diff-pane-scrolls-instead-of-breaking-the-entire-page";

